  PresenceMatrixSchema,
  RecursiveNodeSchema,
  StringNetworkRulesSchema,
  ValidationMatrixSchema,
  WellKnownRuleMatrixSchema,
} from "./gen/protoform/conformance/v1/conformance_pb.js";
import { Editions2024MatrixSchema } from "./gen/protoform/conformance/v1/editions_2024_pb.js";
export type DemoSchemaKey =
  | "any"
  | "batch-create"
  | "batch-delete"
  | "batch-get"
  | "batch-update"
  | "book"
  | "cel"
  | "collections"
  | "commit-policy"
  | "create-book"
  | "delete-book"
  | "dynamic-json"
  | "editions"
  | "export-books"
  | "get-book"
  | "import-books"
  | "integers"
  | "list-books"
  | "numeric"
  | "presence"
  | "provision-capacity"
  | "purge-books"
  | "recursive"
  | "run-job"
  | "string-network"
  | "time-range"
  | "undelete-book"
  | "update-book"
  | "update-settings"
  | "validation"
  | "well-known";

export interface DemoSchema {
  defaultValues: Record<string, unknown>;
  schema: DescMessage;
}

const schemas = {
  any: AnyMatrixSchema,
  "batch-create": BatchCreateBooksRequestSchema,
  "batch-delete": BatchDeleteBooksRequestSchema,
  "batch-get": BatchGetBooksRequestSchema,
  "batch-update": BatchUpdateBooksRequestSchema,
  book: BookSchema,
  cel: CelRuleMatrixSchema,
  collections: CollectionMatrixSchema,
