      return {
        parent: "publishers/acme",
        requests: [validCreateBook],
      };
    case "batch-delete":
      return {
        parent: "publishers/acme",
        requests: [validDeleteBook],
      };
    case "batch-get":
      return {
        names: ["publishers/acme/books/protoform-guide", "publishers/acme/books/api-design"],
        parent: "publishers/acme",
      };
    case "batch-update":
      return {
        parent: "publishers/acme",
        requests: [validUpdateBook],
      };
