      return {
        booleanValue: "ok",
        child: { name: "child-primary" },
        children: [{ name: "child-one" }, { name: "child-two" }],
        messageValue: "ok",
        secondMessageValue: "ok",
        stringValue: "ok",
      };
    case "collections":
      return {
        boolKeys: [{ key: true, value: "enabled" }],
        children: [{ name: "primary" }],
        flags: [true, false],
        identifiers: ["9007199254740993"],
        int32Keys: [{ key: 1, value: "one" }],
        ratios: [0.25, 0.75],
        statuses: [1, 2],
      };
