      const objectValue = fromJson(StructSchema, {
        enabled: true,
        theme: "dark",
      });

      return {
        anyValue: anyPack(StructSchema, objectValue),
        listValue: fromJson(ListValueSchema, ["overview", 3, true]),
        objectValue,
        scalarOrNestedValue: fromJson(ValueSchema, {
          rollout: "canary",
        }),
      };
    }
    case "editions":
      return {
        displayName: "Protoform Editions 2024",
      };
    case "export-books":
      return {
        destination: {
          case: "cloudStorageDestination",
          value: { uri: "gs://protoform-demos/books.ndjson" },
        },
        filter: "state = ACTIVE",
        parent: "publishers/acme",
      };
    case "get-book":
      return { name: "publishers/acme/books/protoform-guide" };
    case "import-books":
      return {
        isbnPrefix: "978",
        parent: "publishers/acme",
        source: {
          case: "cloudStorageSource",
          value: { uri: "gs://protoform-demos/books.ndjson" },
        },
      };
    case "integers":
      return {
        fixed32Allowed: 7,
        fixed32Const: 7,
        fixed32Denied: 7,
        fixed32Range: 7,
        fixed64Allowed: "7",
        fixed64Const: "7",
        fixed64Denied: "7",
        fixed64Range: "7",
        int32Allowed: 7,
        int32Const: 7,
        int32Denied: 7,
        int32Range: 7,
        int64Allowed: "7",
        int64Const: "7",
        int64Denied: "7",
        int64Range: "7",
        sfixed32Allowed: 7,
        sfixed32Const: 7,
        sfixed32Denied: 7,
        sfixed32Range: 7,
        sfixed64Allowed: "7",
        sfixed64Const: "7",
        sfixed64Denied: "7",
        sfixed64Range: "7",
        sint32Allowed: 7,
        sint32Const: 7,
        sint32Denied: 7,
        sint32Range: 7,
        sint64Allowed: "7",
        sint64Const: "7",
        sint64Denied: "7",
        sint64Range: "7",
        uint32Allowed: 7,
        uint32Const: 7,
        uint32Denied: 7,
        uint32Range: 7,
        uint64Allowed: "7",
        uint64Const: "7",
        uint64Denied: "7",
        uint64Range: "7",
      };
    case "list-books":
      return {
        filter: "state = ACTIVE",
        orderBy: "display_name",
        pageSize: 25,
        pageToken: "",
        parent: "publishers/acme",
        returnPartialSuccess: false,
      };
    case "numeric":
      return {
        doubleValue: 99.95,
        enabled: true,
        fixed32Value: 42,
        fixed64Value: "9007199254740993",
        floatValue: 0.75,
        int32Value: -12,
        sfixed32Value: -24,
        sfixed64Value: "-9007199254740993",
        sint32Value: -6,
        sint64Value: "-9007199254740992",
        uint32Value: 24,
      };
    case "presence":
      return {
        approved: false,
        bytesWrapper: "cHJvdG9mb3Jt",
        child: { name: "primary" },
        doubleWrapper: 3.14,
        floatWrapper: 0.75,
        int64Wrapper: "9007199254740993",
        optionalEnabled: true,
        selection: { case: "label", value: "present" },
        uint32Wrapper: 42,
        uint64Wrapper: "9007199254740994",
      };
    case "provision-capacity":
      return {
        currencyCode: "GBP",
        languageCode: "en-GB",
        regionCode: "GB",
        replicaCount: 3,
        storageGibibytes: "64",
        timeZone: "Europe/London",
      };
